local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()

local Window = Rayfield:CreateWindow({
   Name = "Wacky Wizards | Magos Malucos",
   LoadingTitle = "Carregando Script...",
   LoadingSubtitle = "Delta Edition - Por Gemini",
   ConfigurationSaving = {
      Enabled = false,
      FolderName = nil, 
      FileName = "WackyHub"
   },
   Discord = {
      Enabled = false,
      Invite = "noinvitelink", 
      RememberJoins = true 
   },
   KeySystem = false, 
})

-- ================== ABA PRINCIPAL ==================
local TabHome = Window:CreateTab("Itens Grátis", 4483362458) 

local SectionItems = TabHome:CreateSection("Farm de Ingredientes")

TabHome:CreateParagraph({Title = "Como funciona:", Content = "Este botão teleporta você rapidamente para ingredientes que estão jogados no chão pelo mapa."})

TabHome:CreateButton({
   Name = "🔎 Coletar Ingredientes do Mapa",
   Callback = function()
        local player = game.Players.LocalPlayer
        -- Procura por ferramentas ou objetos interagíveis
        for _, v in pairs(workspace:GetDescendants()) do
            if v:IsA("TouchTransmitter") and v.Parent and v.Parent:IsA("Part") then
               -- Verifica se não é parte do próprio player ou killbrick
               if v.Parent.Name ~= "HumanoidRootPart" and not v.Parent.Name:lower():find("lava") then
                    if player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
                        -- Teleporta
                        player.Character.HumanoidRootPart.CFrame = v.Parent.CFrame
                        wait(0.2) -- Pequena pausa para o jogo registrar o toque
                    end
               end
            end
        end
        Rayfield:Notify({Title = "Sucesso", Content = "Varredura do mapa concluída!", Duration = 5})
   end,
})

-- ================== ABA TELEPORTES ==================
local TabTP = Window:CreateTab("Teleportes", 4483362458)
local SectionTP = TabTP:CreateSection("Locais do Mapa")

TabTP:CreateButton({
   Name = "🏠 Ir para o Caldeirão (Spawn)",
   Callback = function()
        game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame = CFrame.new(0, 10, 0)
   end,
})

TabTP:CreateButton({
   Name = "🌋 Vulcão (Feijão)",
   Callback = function()
        game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame = CFrame.new(-390, 150, 180)
   end,
})

TabTP:CreateButton({
   Name = "🌊 Cachoeira",
   Callback = function()
        game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame = CFrame.new(-276, 120, -320)
   end,
})

TabTP:CreateButton({
   Name = "🕷️ Caverna da Aranha",
   Callback = function()
        game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame = CFrame.new(50, 40, 580)
   end,
})

TabTP:CreateButton({
   Name = "🏜️ Deserto",
   Callback = function()
        game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame = CFrame.new(460, 80, -300)
   end,
})

TabTP:CreateButton({
   Name = "💧 Lago",
   Callback = function()
        game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame = CFrame.new(-150, 15, -150)
   end,
})

-- ================== ABA JOGADOR ==================
local TabPlayer = Window:CreateTab("Jogador", 4483362458)
local SectionPlayer = TabPlayer:CreateSection("Atributos")

TabPlayer:CreateSlider({
   Name = "Velocidade (WalkSpeed)",
   Range = {16, 200},
   Increment = 1,
   Suffix = "Speed",
   CurrentValue = 16,
   Flag = "WS", 
   Callback = function(Value)
        game.Players.LocalPlayer.Character.Humanoid.WalkSpeed = Value
   end,
})

TabPlayer:CreateSlider({
   Name = "Pulo (JumpPower)",
   Range = {50, 300},
   Increment = 1,
   Suffix = "Jump",
   CurrentValue = 50,
   Flag = "JP", 
   Callback = function(Value)
        game.Players.LocalPlayer.Character.Humanoid.JumpPower = Value
   end,
})

Rayfield:LoadConfiguration()
